"Ab 20 Minuten Spielzeit kannst du dem Entwickler eine Rückmeldung geben. Verschickt wird sie nur, wenn du selbst auf „Per E-Mail senden“ klickst (öffnet dein Mailprogramm) oder den Text für Discord kopierst und abschickst. Was du ins Formular schreibst, auch das freiwillige Kontaktfeld, wird nicht gespeichert.":"After 20 minutes of playtime you can send feedback to the developer. It is only sent if you click “Send by email” yourself (opens your mail app) or copy the text for Discord and send it. What you write in the form, including the optional contact field, is not stored.",
