"Ab jetzt sollte man zusammen spielen können, und zwar ohne teuren Spielserver: Die Browser der Spieler verbinden sich direkt miteinander, ein Raumcode reicht. Bis zu 32 Spieler, Bots füllen auf, und ein Anti-Cheat prüft die Treffer. Weil ich mir gerade eine VR-Brille geholt hatte, kam auch noch ein VR-Modus für die Meta Quest 3 dazu.":"From now on you should be able to play together – without an expensive game server: the players’ browsers connect directly to each other, a room code is all it takes. Up to 32 players, bots fill up the rest, and an anti-cheat checks the hits. Because I had just bought a VR headset, a VR mode for the Meta Quest 3 was added too.",
