"Am Eingang bereit!":"Ready at the entrance!",
"Am Nordkai liegt der Frachter „Seeschwalbe“ mit Kessars gefälschten Uniformen und Sprengstoff. Schleich dich mit Weber über das Terminal, markiere die Container und hol den erpressten Kapitän heraus – ohne Alarm.":"The freighter “Seeschwalbe” lies at North Quay with Kessar’s fake uniforms and explosives. Sneak across the terminal with Weber, mark the containers and get the blackmailed captain out – without raising the alarm.",
"Am Schießstand Hohenfeld lernst du unter Oberfeldwebel Krell alles, was die Kampagne verlangt: Bewegung, Waffen, Granaten, Ausrüstung, Befehle an den Trupp und den Geländewagen. Jeder Schritt wartet auf dich.":"At the Hohenfeld range, Sergeant First Class Krell teaches you everything the campaign demands: movement, weapons, grenades, equipment, squad orders and the off-road vehicle. Every step waits for you.",
"Am Vorderschaft: Gewehr beidhändig führen (einhändig streut es stark). An der Brust: Granate nehmen, Abzug zieht den Splint, Loslassen wirft.":"On the handguard: hold the rifle with both hands (one-handed it spreads a lot). At the chest: take a grenade, the trigger pulls the pin, letting go throws.",
