"Amboss an Falke 2: Ihr habt Feuerfreiheit ab der Sperrlinie. Viel Glück.":"Anvil to Falcon 2: you’re weapons free from the blocking line on. Good luck.",
"Amboss an Falken: Aufklärung meldet zwanzig Fahrzeuge im Anmarsch auf die Höhe. Die Kompanie braucht noch eine halbe Stunde.":"Anvil to Falcons: recon reports twenty vehicles advancing on the hill. The company needs another half hour.",
"Amboss an alle Falken: Auftrag erfüllt. Sammeln am Markt. Ende.":"Anvil to all Falcons: mission accomplished. Assemble at the market. Out.",
"Amboss an alle Falken: Korvanische Panzer haben um vier Uhr die Grenze bei Mirenfurt überschritten. Vor uns liegt ihre Sperrlinie.":"Anvil to all Falcons: Korvanian tanks crossed the border at Mirenfurt at four o’clock. Their blocking line lies ahead of us.",
"Amboss: Die Kompanie ist auf der Höhe. Der Feind zieht sich zurück.":"Anvil: the company is on the hill. The enemy is withdrawing.",
