"Angriff – auf mein Zeichen!":"Attack – on my mark!",
"Anker an Eisen-Zug: Aufklärung meldet feindliche Pioniere an der Flussbrücke. Dazu mindestens zwei Kampfpanzer.":"Anchor to Iron Platoon: recon reports enemy engineers at the river bridge. Plus at least two main battle tanks.",
"Anker an Falke: Das Relais schweigt. Keine Sendung ist hinausgegangen. Ich wiederhole: keine Sendung.":"Anchor to Falke: the relay is silent. No broadcast went out. I repeat: no broadcast.",
"Anker an Geleit: Die Kommission erwartet Major Daren um neunzehn Uhr am Nordhang. Die Straße durchs Dorf ist frei gemeldet.":"Anchor to Escort: the commission expects Major Daren at nineteen hundred on the north slope. The road through the village is reported clear.",
"Anker an Kapelle: Die Delegationen sind unterwegs. Ankunft in etwa zwanzig Minuten. Bewegung im Trichterfeld nördlich von euch.":"Anchor to Chapel: the delegations are on their way. Arrival in about twenty minutes. Movement in the crater field north of you.",
"Anker an Libelle 1: Kessars Maschine wird auf dem Vorfeld betankt. Abflug in etwa zwanzig Minuten. Zwei Flugabwehrstellungen gemeldet.":"Anchor to Libelle 1: Kessar’s aircraft is being refueled on the apron. Departure in about twenty minutes. Two anti-aircraft positions reported.",
"Anker an Libelle 1: Luftraum frei. Zwei Jäger fliegen das Vorfeld an.":"Anchor to Libelle 1: airspace clear. Two fighters inbound to the apron.",
"Anker an Trupp Falke: Das Relais von Sant Aurel sendet einen Prüfton. In elf Minuten geht Kessars Botschaft an alle Einheiten beider Seiten.":"Anchor to Squad Falke: the Sant Aurel relay is sending a test tone. In eleven minutes Kessar’s message goes out to every unit on both sides.",
"Anker an Trupp Falke: Funkspruch vom Fliegerhorst Hagenmoor. Die Graue Kompanie hält zwanzig Leute vom Bodenpersonal in den Unterkünften fest.":"Anchor to Squad Falke: radio call from Hagenmoor Air Base. The Gray Company is holding twenty ground crew in the quarters.",
"Anker an Trupp Falke: Peilung bestätigt. Die Stimme sendet vom Funkhügel, jede Nacht um zwei Uhr, immer nur vierzig Sekunden.":"Anchor to Squad Falke: bearing confirmed. The voice transmits from the radio hill, every night at two, always for just forty seconds.",
"Anker an Trupp Lenz: Der Frachter Seeschwalbe liegt seit gestern Abend am Nordkai. Ladung laut Papieren: Ersatzteile.":"Anchor to Squad Lenz: the freighter Seeschwalbe has been at North Quay since last night. Cargo according to the papers: spare parts.",
"Anker an Trupp Lenz: Im Staatsarchiv brennt seit einer Stunde Licht. Niemand hat die Wachablösung gemeldet.":"Anchor to Squad Lenz: lights have been on in the state archive for an hour. Nobody reported the guard change.",
"Anker an Werk Sieben: Busse und Lkw sind unterwegs. Erste Abfahrt in vier Minuten.":"Anchor to Factory Seven: buses and trucks are on their way. First departure in four minutes.",
"Anker an alle Einheiten: Das Funkrelais Sant Aurel sendet seit drei Stunden nicht mehr. Keine Verbindung ins Tal.":"Anchor to all units: the Sant Aurel radio relay has been off the air for three hours. No contact with the valley.",
"Anker an alle Einheiten: Starke Kräfte der Brigade Kessar vor der Nordstellung. Infanterie, Panzer, mindestens zwei Bataillone.":"Anchor to all units: strong Kessar Brigade forces in front of the north line. Infantry, tanks, at least two battalions.",
"Anker an alle: Das Funkhaus von Veldmark ist besetzt. Kessar hält die Belegschaft fest. Die Straßen füllen sich – die Stadt geht zur Arbeit.":"Anchor to all: the Veldmark broadcasting house is occupied. Kessar is holding the staff. The streets are filling up – the city is heading to work.",
"Anker an alle: Der Brand oberhalb des Holzplatzes breitet sich nach Süden aus. Funkkontakt zu den Arbeitern abgerissen.":"Anchor to all: the fire above the timber yard is spreading south. Radio contact with the workers lost.",
"Anker an alle: Die Brigade Kessar weicht zurück. Ich wiederhole: Sie weichen zurück!":"Anchor to all: the Kessar Brigade is falling back. I repeat: they’re falling back!",
"Anker an alle: Kessars Verbände ziehen sich auf breiter Front zurück. Die Linie hält.":"Anchor to all: Kessar’s forces are withdrawing along a broad front. The line holds.",
"Anker an alle: Sitzung der Waffenstillstandskommission beginnt um zwölf Uhr. Etwa dreihundert Menschen auf dem Lindenplatz.":"Anchor to all: the ceasefire commission session begins at twelve. About three hundred people on Lindenplatz.",
"Anker hat mitgehört. Gute Arbeit, Falke. Wir verlegen sofort zum Werk und bringen die Leute dort raus.":"Anchor heard everything. Good work, Falke. We move to the factory right away and get the people out.",
"Anker hier – der Prüfton ist weg! Das Relais ist stumm!":"Anchor here – the test tone is gone! The relay is silent!",
"Anker hier – wir empfangen euch wieder! Relais Sant Aurel ist zurück im Netz.":"Anchor here – we’re receiving you again! Sant Aurel relay is back on the net.",
"Anker hier. Zwei Jäger sind in der Luft. Markiert uns die Kolonne, dann schlagen sie zu.":"Anchor here. Two fighters are airborne. Mark the column for us, then they’ll strike.",
"Anker hier: Druck in der Talleitung ist stabil. Die Pumpen laufen.":"Anchor here: pressure in the valley main is stable. The pumps are running.",
"Anker hört euch. Was braucht ihr?":"Anchor hears you. What do you need?",
"Anker: Geleit hat den Nordhang erreicht. Der Zeuge ist unverletzt.":"Anchor: the escort has reached the north slope. The witness is unharmed.",
"Anker: Kessars Maschine brennt. Der Flugplatz ist in unserer Hand.":"Anchor: Kessar’s aircraft is burning. The airfield is ours.",
"Anker: Lindenplatz gesichert. Keine Toten unter den Zivilisten. Drei Späher und elf Söldner in Gewahrsam.":"Anchor: Lindenplatz secured. No civilian deaths. Three scouts and eleven mercenaries in custody.",
