"Arcade":"Arcade",
"Arcade zeigt dir alles und heilt schnell. Realistisch blendet Gegner und fast das ganze HUD aus und macht Treffer tödlicher. Simulation geht noch weiter: Magazine, Durchladen, Ladehemmungen, Verwundungen, kein HUD. Der Vergleich steht unter":"Arcade shows you everything and heals fast. Realistic hides enemies and almost the whole HUD and makes hits deadlier. Simulation goes further: magazines, chambering, malfunctions, wounds, no HUD. The comparison is under",
"Arcade – {0}":"Arcade – {0}",
