"Arcade: Du fährst und schießt allein (Rolle gilt nur in der Simulation).":"Arcade: you drive and shoot alone (the role only applies in simulation).",
"Arcade: W/A/S/D fahren, Maus richten, Linksklick Feuer, 1–4 Munition.":"Arcade: W/A/S/D to drive, mouse to aim, left click to fire, 1–4 ammo.",
"Arcade: das bekannte Spiel. Realistisch: keine Gegneranzeigen, minimales HUD, mehr Schaden, langsamere Heilung.":"Arcade: the familiar game. Realistic: no enemy markers, minimal HUD, more damage, slower healing.",
"Arcade: du fährst und schießt; Platzwechsel Richtschütze ↔ Fahrer ↔ Kommandant mit dem Sitzrad (K halten).":"Arcade: you drive and shoot; switch seats gunner ↔ driver ↔ commander with the seat wheel (hold K).",
