"Auf dem iPhone erlaubt iOS Webseiten kein Vollbild.":"On iPhone, iOS does not allow full screen for websites.",
"Auf den Nullpunkt schießen":"Shoot at the zero point",
"Auf den meisten aktuellen Handys ja, auf der Grafikstufe „Niedrig“ oder „Mittel“. Das Handy quer halten. Nötig ist ein Browser mit WebGL 2. Die Übersicht steht unter":"On most current phones yes, on graphics level “Low” or “Medium”. Hold the phone sideways. You need a browser with WebGL 2. The overview is under",
"Auf der rechten Hälfte ziehen. Optional Gyro (Einstellungen → Steuerung).":"Drag on the right half. Optional gyro (Settings → Controls).",
"Auf eine Meile":"From a mile away",
"Auf fünfzig Meter und weiter: hinlegen, anlegen, ruhig atmen.":"At fifty meters and beyond: go prone, aim, breathe calmly.",
"Auf vielen echten Grafikkarten war plötzlich der Boden unsichtbar. Der Grund: Der Gelände-Shader brauchte 17 Texturen, dort sind aber nur 16 erlaubt. In der Testumgebung fiel das nicht auf, weil sie 32 erlaubt. Der Hotfix kam noch am selben Abend. In den Tagen davor waren neue Ego-Hände und neue Körper für die Soldaten entstanden. Danach Akt III der Kampagne mit den Missionen 12 bis 15 und die Panzersimulation: vier Plätze, jeder Handgriff selbst, mit Tutorial, Hilfe oder ganz frei.":"On many real graphics cards the ground suddenly became invisible. The reason: the terrain shader needed 17 textures, but only 16 are allowed there. It went unnoticed in the test environment because it allows 32. The hotfix came that same evening. In the days before, new first-person hands and new bodies for the soldiers had been created. After that came Act III of the campaign with missions 12 to 15, and the tank simulation: four stations, every action yourself, with tutorial, help or completely free.",
