"Auflösung der Fotoscan-Texturen (Böden, Wände, Holz, Metall). Ultra lädt 2048er-Scans: deutlich schärfer aus der Nähe, braucht mehr Grafikspeicher und Ladezeit. Nur auf Qualitätsstufe Hoch/Ultra und nicht auf Telefonen. Gilt ab dem nächsten Match.":"Resolution of photo-scanned textures (floors, walls, wood, metal). Ultra loads 2048 scans: much sharper up close, needs more video memory and loading time. Only on quality High/Ultra and not on phones. Applies from the next match.",
