"Bleibt die Frage, um die es bei dem Experiment eigentlich geht: Merkt man einem Spiel heute noch an, dass eine KI den Code geschrieben hat? Wenn es dir beim Spielen nicht aufgefallen ist, ist das vielleicht schon die Antwort.":"That leaves the question the experiment is really about: can you still tell today that an AI wrote a game’s code? If you didn’t notice while playing, maybe that’s already the answer.",
