"Bullpup mit 50-Schuss-Magazin, das quer über dem Lauf liegt. Auf Türrahmen-Distanz die schnellste Waffe im Arsenal – dahinter verpufft ihre Wirkung rasch.":"Bullpup with a 50-round magazine lying across the top of the barrel. At doorway range the fastest weapon in the arsenal – beyond that its effect fades quickly.",
"Bullpup mit integrierter 1,6-fach-Optik: voller Gewehrlauf in kompaktem Gehäuse, präzise bis weit über die Platzmitte. Das Magazin sitzt hinter dem Griff – der Wechsel dauert.":"Bullpup with integrated 1.6× optic: a full rifle barrel in a compact body, precise well past the middle of the square. The magazine sits behind the grip – changing it takes time.",
"Bullpup-Sturmgewehr mit Rotpunkt: langer Lauf im kurzen Gehäuse, ruhig im Dauerfeuer und präzise bis weit über die Straße. Das Magazin hinter dem Griff will geübt gewechselt werden.":"Bullpup assault rifle with red dot: long barrel in a short body, steady on full auto and precise well across the street. The magazine behind the grip takes practice to change.",
