"Diese Waffe passt nicht zur Rolle.":"This weapon doesn’t suit the role.",
"Dieser Abschnitt konnte nicht aufgebaut werden.":"This section could not be built.",
"Dieser Browser meldet keine VR-Brille (WebXR „immersive-vr“). Auf der Meta Quest 3: diese Seite im Quest-Browser öffnen. Am PC: Quest per Air Link oder Link-Kabel verbinden und die Seite in Chrome oder Edge öffnen (HTTPS).":"This browser reports no VR headset (WebXR “immersive-vr”). On Meta Quest 3: open this page in the Quest browser. On PC: connect the Quest via Air Link or Link cable and open the page in Chrome or Edge (HTTPS).",
