"Doppel":"Double kill",
"Doppelflinte mit Kipplauf: zwei Läufe, zwei Abzüge, zwei Schuss – dann wird geknickt. Auf Raumlänge endgültig, im Doppelschuss bis über die Hofmitte.":"Break-action double-barrel: two barrels, two triggers, two shots – then you break it open. Final at room length, with a double shot past the middle of the yard.",
