"Dorf ist ruhig. Lagemeldung, Leutnant?":"Village is quiet. Status report, Lieutenant?",
"Dorf ist sauber. Ein paar Leute im Keller der Kapelle – denen geht es gut.":"Village is clear. A few people in the chapel cellar – they’re fine.",
