"Eingang":"Entrance",
"Eingegrabene Pak, ein Bunker an der Straße und dahinter eine Funkstelle, die ihre Artillerie lenkt. Ohne die Funkstelle sind sie blind.":"Dug-in AT guns, a bunker by the road and behind it a radio post directing their artillery. Without the radio post they’re blind.",
