"Einmal: taktisch, das alte Magazin kommt zurück in die Tasche (langsamer). Zweimal schnell: Notfall – das alte fällt zu Boden, samt Restpatronen.":"Once: tactical, the old magazine goes back in the pouch (slower). Twice quickly: emergency – the old one drops to the ground, remaining rounds and all.",
