"Einschusslöcher je Kaliber, Querschläger und Durchschüsse. Dauerfeuer frisst sich durch Wände, Sprengungen reißen begehbare Breschen mit gebrochenen Rändern, Ruß und Staub. Türen fallen aus zerschossenen Scharnieren, Bäume kippen, Panzer schieben Gebäude ein.":"Bullet holes by caliber, ricochets and penetrations. Sustained fire eats through walls, explosions tear walkable breaches with broken edges, soot and dust. Doors fall from shot-out hinges, trees topple, tanks push buildings in.",
"Einschüssiger 40-mm-Granatwerfer: Splittergranate im hohen Bogen, scharf ab 12 m. Räumt Fenster, Gräben und Stellungen.":"Single-shot 40 mm grenade launcher: high-arcing frag grenade, armed from 12 m. Clears windows, trenches and positions.",
