"Erst anhalten":"Stop first",
"Erst aussteigen.":"Get out first.",
"Erst das Lager, dann die Brücke. Danach sofort zurück. Ich will euch vor Sonnenaufgang wiedersehen.":"Camp first, then the bridge. Then straight back. I want to see you again before sunrise.",
"Erst die Kapelle, dann das Gerät. Und jeder Verwundete wird geborgen – gleich, welche Uniform er trägt.":"First the chapel, then the radio. And every wounded man gets recovered – no matter what uniform he wears.",
