"Erste Fassungen von Mehrspieler und VR, neue Animationen, Befehlsrad und der Modus „Nur Messer“.":"First versions of multiplayer and VR, new animations, command wheel and the “Knives only” mode.",
"Erste Flugabwehr, gleich vor uns. Wachen ausschalten, dann Ladung dran.":"First anti-aircraft position, right in front of us. Take out the guards, then plant the charge.",
