"Erziele {n} Abschüsse":"Get {n} kills",
"Eröffne Raum …":"Opening room …",
"Es gibt keine Munitionsanzeige. Magazin herausziehen, wiegen, ansehen – du bekommst nur eine Schätzung.":"There is no ammo counter. Pull the magazine, weigh it, look at it – you only get an estimate.",
"Es gibt nur eine Stellung – und sie bleibt nicht lange an einem Ort. Wer sie allein hält, bekommt jede Sekunde einen Punkt; stehen beide Teams drin, ist sie umkämpft und niemand punktet. Kurz vor dem Wechsel taucht die nächste Stellung gedimmt auf: Wer früh umsetzt, hat den besseren Winkel.":"There is only one hardpoint – and it doesn’t stay in one place for long. Whoever holds it alone gets a point every second; if both teams are inside, it’s contested and nobody scores. Shortly before it moves, the next hardpoint appears dimmed: rotate early for the better angle.",
"Es ruckelt. Was kann ich tun?":"It stutters. What can I do?",
"Esc beendet den Test.":"Esc ends the test.",
"Etwa {0} von 4 geladen":"About {0} of 4 loaded",
"Evakuierung":"Evacuation",
"Experimentell: Bei so vielen Bots kann die Bildrate auf diesem Gerät unter 30 FPS fallen.":"Experimental: with this many bots the frame rate on this device may drop below 30 FPS.",
"Experimentell: Über 100 je Seite braucht einen starken Prozessor (6+ Kerne). Ferne Soldaten erscheinen als vereinfachte Silhouetten und denken seltener; die Bildrate kann unter 60 FPS fallen.":"Experimental: over 100 per side needs a strong CPU (6+ cores). Distant soldiers appear as simplified silhouettes and think less often; the frame rate may drop below 60 FPS.",
"Extrem":"Extreme",
"FEUER halten. Quer wischen: drehen.":"Hold FIRE. Swipe sideways: rotate.",
"FEUERLÖSCHER":"FIRE EXTINGUISHER",
