"FUNK 1":"RADIO 1",
"FUNK 2":"RADIO 2",
"FXAA ist billig, SMAA schärfer und ruhiger. TAA verrechnet mehrere Bilder: feine Details (Zäune, Gras, Kanten) und weiche Schatten stehen ruhig, das Bild wird etwas weicher.":"FXAA is cheap, SMAA sharper and steadier. TAA blends several frames: fine details (fences, grass, edges) and soft shadows stay stable, the image gets a bit softer.",
