"Fahrt vorn, aber nicht zu weit. Die Wagen sind nicht gepanzert. Ohne sie steht morgen die ganze Kompanie still.":"Drive up front, but not too far. The trucks aren’t armored. Without them the whole company stands still tomorrow.",
