"Feindpanzer von Westen, auf dem Weg vom Gehöft! Ich kann den Turm nicht drehen – ihr müsst ihn zu Fuß stoppen!":"Enemy tank from the west, on the road from the farmstead! I can’t traverse the turret – you have to stop it on foot!",
"Feine Schatten dort, wo Dinge den Boden berühren (Füße, Kisten, Leisten) – ergänzt die Schattenkarte. Ab „Hoch“.":"Fine shadows where things touch the ground (feet, crates, trims) – complements the shadow map. From “High”.",
"Feld anklicken und eine Taste aus der Liste wählen. H = Haupthand (Waffe), N = Nebenhand. A/X ist die untere, B/Y die obere Taste.":"Click a field and choose a button from the list. H = main hand (weapon), N = off hand. A/X is the lower, B/Y the upper button.",
"Feld anklicken, dann Taste oder Maustaste drücken. Esc bricht ab. Bis zu drei Belegungen je Aktion.":"Click a field, then press a key or mouse button. Esc cancels. Up to three bindings per action.",
"Feld antippen. Mitte schließt.":"Tap a field. Center closes.",
