"Feldwebel … Anker meldet Rauch über dem Brandwald. Das ganze Waldstück oberhalb des Holzplatzes steht in Flammen.":"Sergeant … Anchor reports smoke over the Burnt Forest. The whole woodland above the timber yard is in flames.",
"Feldwebel … ich habe Kessars Funk entschlüsselt. Er zieht alles zusammen, was ihm folgt. Morgen früh, im Niemandsland.":"Sergeant … I’ve decrypted Kessar’s radio. He’s gathering everything that follows him. Tomorrow morning, in No Man’s Land.",
"Feldwebel! Anker meldet: Das Funkrelais in Sant Aurel ist verstummt. Keine Verbindung mehr ins Tal.":"Sergeant! Anchor reports: the radio relay in Sant Aurel has gone silent. No more contact with the valley.",
