"Für den Mehrspieler eine normale Internetverbindung. Offline läuft alles, was du schon einmal geladen hast.":"For multiplayer, a normal internet connection. Offline, everything you have loaded before still runs.",
"Für dieses Gerät empfohlen: {0}. Mehr Bots können ruckeln und das Gerät warm machen.":"Recommended for this device: {0}. More bots may stutter and warm up the device.",
"Für kleine Studios und für alle, die gerade erst anfangen, öffnet das eine Tür. Ein Spiel zu entwickeln verschlingt normalerweise viel Geld; selbst das größte Abo bei Claude ist günstiger als das, was die Entwicklung eines Indie-Spiels sonst kostet. Wer selbst programmieren kann, gibt dabei nichts aus der Hand: Er kann weiter eigene Wege gehen und prüfen, was die KI geschrieben hat. Und wer es nicht kann, so wie ich, bekommt überhaupt erst die Chance, aus einer Idee ein fertiges Spiel zu machen.":"For small studios and for everyone just starting out, this opens a door. Developing a game normally eats up a lot of money; even the biggest Claude subscription is cheaper than what developing an indie game usually costs. Those who can program themselves don’t give anything away: they can still go their own way and check what the AI wrote. And those who can’t, like me, get the chance to turn an idea into a finished game in the first place.",
