"Großes Studio":"Big studio",
"Großkalibrige Pistole mit sieben Patronen und spürbarem Hochschlag. Drei Treffer genügen auf kurze Distanz – zwei, wenn der erste den Kopf findet.":"Large-caliber pistol with seven rounds and noticeable muzzle flip. Three hits do it at close range – two if the first finds the head.",
"Großkampf auf weiter Karte: Nehmt die Flaggen A bis E ein, haltet sie und lasst den Gegner ausbluten. Jeder Wiedereinstieg kostet ein Ticket, wer mehr Flaggen hält, zieht dem Gegner laufend Tickets ab. Trupps zu viert, Einsatzkarte mit HQ-, Flaggen- und Truppspawns, Panzer und Geländewagen.":"Large-scale battle on a wide map: take flags A to E, hold them and bleed the enemy dry. Every respawn costs a ticket; whoever holds more flags keeps draining the enemy’s tickets. Squads of four, deployment map with HQ, flag and squad spawns, tanks and off-road vehicles.",
"Großkarte":"Large map",
"Großkarte mit Luftunterstützung (verbündete Jets überfliegen per air.spawn jet airborne)":"Large map with air support (allied jets fly over)",
"Großkarte ·":"Large map ·",
"Großkarte: Fluss mit Brücke, Dorf, Gehöft, Kieswerk und Funkhügel – fünf Flaggen.":"Large map: river with bridge, village, farmstead, gravel works and radio hill – five flags.",
"Großkarte: Schützengräben, Granattrichter, Stacheldraht, Ruinen – fünf Flaggen.":"Large map: trenches, shell craters, barbed wire, ruins – five flags.",
"Großkarte: Startbahn, Hangars, Tower, Tanklager, Radar, Kaserne – Jets starten vom Boden.":"Large map: runway, hangars, tower, fuel depot, radar, barracks – jets take off from the ground.",
"Großkarte: verbrannter Wald, Schützengräben mit Sandsäcken, Gittermasten – fünf Flaggen.":"Large map: burnt forest, trenches with sandbags, lattice pylons – five flags.",
"Großvater, wir sind an deiner Furt. Und diesmal kommen alle heim.":"Grandfather, we’re at your ford. And this time everyone comes home.",
