"Gurtgespeist, mit Zweibein und hundert Schuss Geduld. Der Hammer hält ganze Korridore dicht – solange ihn niemand beim langsamen Anlegen überrascht.":"Belt-fed, with bipod and a hundred rounds of patience. The Hammer locks down entire corridors – as long as nobody surprises it while slowly raising it.",
