"Gut erkannt!":"Well spotted!",
"Gut gehalten. Ihre Infanterie ist erschöpft – jetzt brauchen wir das Funkgerät, bevor die Panzer kommen.":"Well held. Their infantry is exhausted – now we need the radio before the tanks come.",
"Gut gemacht, Falke. Du hast heute niemanden verloren. Ruht euch aus – um fünf Uhr fliegt ihr nach Hagenmoor. Lenz besteht darauf, mitzukommen.":"Well done, Falke. You didn’t lose anyone today. Get some rest – at five you fly to Hagenmoor. Lenz insists on coming along.",
"Gut gemacht. Jetzt in die Löcher – und warten.":"Well done. Now into the holes – and wait.",
"Gut gemacht. Jetzt zum Tor – sie kommen gleich.":"Well done. Now to the gate – they’re coming any moment.",
"Gut gemacht. Kommen Sie zum Vorplatz.":"Well done. Come to the forecourt.",
"Gut getroffen!":"Good hit!",
"Gut so. Von hier siehst du den ganzen Nordplatz. Die Sitzung beginnt gleich.":"Good. From here you see the whole north square. The session is about to start.",
"Gut zu wissen":"Good to know",
"Gut. Die nächste Welle ist schon unterwegs – mit Schützenpanzern und Infanterie.":"Good. The next wave is already on its way – with IFVs and infantry.",
"Gut. Jetzt schnell – sprinten Sie ein Stück.":"Good. Now fast – sprint for a bit.",
"Gut. Motor läuft. Die Kanone ist geladen. Folge der Straße nach Süden.":"Good. Engine’s running. The gun is loaded. Follow the road south.",
"Gut. Schub ganz nach vorn. Bleib auf der Mittellinie. Bei etwa zweihundertfünfzig Stundenkilometern ziehst du sanft – nicht reißen.":"Good. Throttle all the way forward. Stay on the centerline. At about two hundred fifty kilometers per hour, pull gently – don’t yank.",
"Gut. Sender sitzt. Weiter nach Westen.":"Good. Beacon’s on. Continue west.",
"Gute Arbeit. Wir sehen sie jetzt alle. Dein Schuss – dann gehen wir rein.":"Good work. We see them all now. Your shot – then we go in.",
