"Herbst im Tal der Miren. Mit „Falke 2“ und deiner Besatzung brichst du durch Sperrlinien, hältst eine Höhe, sicherst Nachschub und kämpfst bei Nacht mit Wärmebild. Eine Mission spielt achtzig Jahre früher in einem alten Panzer.":"Autumn in the Miren Valley. With “Falcon 2” and your crew you break through blocking lines, hold a hill, secure supplies and fight at night with thermal sights. One mission takes place eighty years earlier in an old tank.",
"Herbst im Tal der Miren: Korvanische Panzer überschreiten die Grenze. Mit „Falke 2“ und deiner Besatzung brichst du durch Sperrlinien, hältst eine Höhe, geleitest Nachschub und schlägst bei Nacht zu.":"Autumn in the Miren Valley: Korvanian tanks cross the border. With “Falcon 2” and your crew you break through blocking lines, hold a hill, escort supplies and strike at night.",
"Herbst im Tal der Miren: Korvanische Panzer überschreiten die Grenze. Mit „Falke 2“ und deiner Besatzung brichst du durch Sperrlinien, hältst eine Höhe, geleitest Nachschub, schlägst bei Nacht zu – und erfährst, warum Oberfeldwebel Asmus die Furt von Mirenfurt so gut kennt.":"Autumn in the Miren Valley: Korvanian tanks cross the border. With “Falcon 2” and your crew you break through blocking lines, hold a hill, escort supplies, strike at night – and learn why Sergeant First Class Asmus knows the ford of Mirenfurt so well.",
"Herr Hauptmann – Kessar sendet. Auf allen Frequenzen gleichzeitig.":"Captain – Kessar is transmitting. On all frequencies at once.",
"Herr Hauptmann – jemand ist auf unserer Frequenz. Offener Kanal, ohne Schlüssel.":"Captain – someone is on our frequency. Open channel, no encryption.",
"Herr Hauptmann … jemand ist auf unserer offenen Frequenz. Kein Rufzeichen. Das Signal kommt nicht aus dem Tal.":"Captain … someone is on our open frequency. No callsign. The signal isn’t coming from the valley.",
"Herr Hauptmann! Das Relais in Sant Aurel – Kessars Leute haben es besetzt. Er will heute Nacht senden, auf allen Kanälen.":"Captain! The relay in Sant Aurel – Kessar’s men have taken it. He wants to broadcast tonight, on all channels.",
"Herrschaft":"Domination",
"Herunterladen":"Download",
"Herunterschalten (Panzer)":"Shift down (tank)",
"Heute":"Today",
"Heute Nacht greifen wir ihr Lager an der Behelfsbrücke an. Dafür bekommt ihr Falke 2 zurück – mit Wärmebild.":"Tonight we attack their camp at the makeshift bridge. For that you get Falcon 2 back – with thermal sight.",
"Hiebdauer":"Swing time",
"Hier Daren, offener Kanal. Ich habe den Befehl erhalten. Ich werde ihn nicht ausführen.":"Daren here, open channel. I’ve received the order. I will not carry it out.",
"Hier Hof. Alles ruhig.":"Farm here. All quiet.",
"Hier Oberst Vesk an die veldmärkischen Truppen. Wir räumen Mirenfurt. Ich bitte um Waffenruhe für unsere Verwundeten.":"This is Colonel Vesk to the Veldmark troops. We are withdrawing from Mirenfurt. I request a ceasefire for our wounded.",
"Hier Rabe 7 – feindliche Panzer an der Linie! Erbitten Feuer auf Planquadrat Mirenfurt Nord!":"This is Raven 7 – enemy tanks at the line! Request fire on grid Mirenfurt North!",
"Hier Vahl. Der Hügel ist verloren. Plan bleibt. Mittag, Lindenplatz. Niemand redet.":"Vahl here. The hill is lost. Plan stands. Noon, Lindenplatz. Nobody talks.",
"Hier haben vor hundert Jahren Männer auf beiden Seiten in Gräben gelegen. Wenn wir hier unterschreiben, versteht jeder, worum es geht.":"A hundred years ago, men on both sides lay in trenches here. If we sign here, everyone will understand what this is about.",
"Hier halten wir. Gräben besetzen, die Leute runter in den Graben!":"We hold here. Man the trenches, get the people down into the trench!",
"Hier herunterladen":"Download here",
"Hier ist es. Die Antenne ist abgerissen – gib mir einen Moment.":"Here it is. The antenna’s torn off – give me a moment.",
"Hier ist kein Platz zum Bauen.":"No room to build here.",
"Hier liegt ein Funkgerät mit Schlüsselliste. Das brauche ich – gib mir Deckung, Falke.":"There’s a radio here with a key list. I need that – cover me, Falke.",
"Hier schießt niemand mehr. Wo ist Kessar?":"Nobody’s shooting anymore. Where is Kessar?",
"Hier spielen":"Play here",
"Hier spricht Major Ilja Daren, Ostbund, Dritte Grenzbrigade. An alle Einheiten beider Seiten.":"This is Major Ilja Daren, Eastern League, Third Border Brigade. To all units on both sides.",
"Hier spricht Major Ilja Daren, Ostbund, Dritte Grenzbrigade. Ich weiß, was Oberst Kessar vorhat.":"This is Major Ilja Daren, Eastern League, Third Border Brigade. I know what Colonel Kessar is planning.",
"Hier spricht Oberst Kessar. Wer das Funkhaus betritt, ist für jeden Toten darin verantwortlich.":"This is Colonel Kessar. Whoever enters the broadcasting house is responsible for every death inside.",
"Hier! Wir sind hier drin! Nicht schießen!":"Here! We’re in here! Don’t shoot!",
