"Hubschrauber, Jets, Panzer und Geländewagen in beiden Gefechtsständen":"Helicopters, jets, tanks and off-road vehicles at both command posts",
"Hubschrauber: W/S steigen/sinken, A/D drehen, Maus neigen, Leertaste schweben.":"Helicopter: W/S climb/descend, A/D turn, mouse tilt, Space hover.",
"Hundert Schuss Sperrfeuer, um dem Team den Weg freizuhalten.":"A hundred rounds of suppressive fire to keep the way clear for the team.",
"Hunderte Granattrichter, die tiefsten voll Wasser":"Hundreds of shell craters, the deepest full of water",
