"In der Verlängerung entschieden":"Decided in overtime",
"In die Stadt. Er sucht sich Menschen, hinter denen er sich verstecken kann.":"Into the city. He’s looking for people to hide behind.",
"In diesem Link steckt kein Raumcode – er sieht so aus: …spielen.html?raum=K7M2QX":"This link contains no room code – it looks like this: …spielen.html?raum=K7M2QX",
"In diesem Modus nicht verfügbar – es gilt „Realistisch“.":"Not available in this mode – “Realistic” applies.",
"In diesen zwei Wochen ist keine neue Fassung erschienen.":"No new version was released in these two weeks.",
"In eigenem Tab spielen":"Play in own tab",
"In neuem Tab öffnen":"Open in new tab",
"In seiner Jacke: ein Notizbuch. Zahlungen, Daten, Treffpunkte. Und immer derselbe Absender – „Kranich“.":"In his jacket: a notebook. Payments, dates, meeting points. And always the same sender – “Kranich”.",
"In unseren Uniformen?":"In our uniforms?",
