"Infiziere {n} Überlebende":"Infect {n} survivors",
"Infiziert":"Infected",
"Infiziert und Waffenspiel gingen online, jede Klasse bekam eine eigene Fähigkeit, im Realismus-Modus muss man Munition bei Gefallenen aufsammeln, und Pioniere können Sandsäcke, MG-Nester und Bunker bauen. Die Waffen bekamen mehr Details. Dazu kam eine neue Karte: eine Zauberbibliothek in einer Steinhalle mit verwinkelten Regalgassen, Galerien und Brücken.":"Infected and Gun Game went online, every class got its own ability, in realism mode you have to collect ammo from the fallen, and engineers can build sandbags, MG nests and bunkers. The weapons got more detail. Plus a new map: a magic library in a stone hall with winding shelf aisles, galleries and bridges.",
"Infizierte":"Infected",
"Infizierte Überlebende":"Survivors infected",
"Infizierte: Messer, Haftgranate, schneller zurück":"Infected: knife, sticky grenade, faster respawn",
