"Inspizieren":"Inspect",
"Installiert – du spielst gerade in der Web-App.":"Installed – you are playing in the web app right now.",
"Installiert. NULLPUNKT liegt jetzt bei deinen Apps.":"Installed. NULLPUNKT is now among your apps.",
"Instandsetzung Nord · Nr. 4471":"Maintenance North · no. 4471",
