"Jaro Vahl lebend festnehmen":"Capture Jaro Vahl alive",
"Je 25 Abschüsse mit 10 verschiedenen Waffen.":"25 kills each with 10 different weapons.",
"Je nach Karte (Niemandsland: 1. Weltkrieg, sonst modern)":"Depends on the map (No Man’s Land: WWI, otherwise modern)",
"Jede Klasse hat drei Ausführungen. Die Teamfarbe an Ärmel und Helm bleibt immer erkennbar.":"Each class has three variants. The team color on sleeve and helmet always stays visible.",
"Jede Waffe hat ihren eigenen Schnitt.":"Every weapon has its own cut.",
"Jede Waffe ist hier frei – auch noch gesperrte zum Probeschießen. Reserve unbegrenzt.":"Every weapon is free here – even locked ones, for test firing. Unlimited reserve.",
"Jede gehaltene Flagge: 1 Punkt alle 4 Sekunden":"Each held flag: 1 point every 4 seconds",
"Jeder Abschuss befördert dich zur nächsten Waffe – von der MP über das Scharfschützengewehr bis zum Kampfmesser. Wer mit der letzten Stufe trifft, gewinnt. Ein Messerabschuss wirft das Opfer eine Stufe zurück.":"Every kill promotes you to the next weapon – from SMG through sniper rifle to the combat knife. Whoever scores a kill on the final level wins. A knife kill sets the victim back one level.",
"Jeder Abschuss bringt Munition für die Waffe, mit der er gelang: ein Magazin, beim Maschinengewehr 20 Schuss direkt in den Gurt. Der Vorrat wächst höchstens ein Magazin über den Startwert. Online entscheidet der Host.":"Every kill grants ammo for the weapon that got it: one magazine, or 20 rounds straight into the belt for machine guns. The reserve grows at most one magazine above the starting amount. Online, the host decides.",
"Jeder Abschuss bringt ein Magazin (MG: 20 Schuss)":"Every kill grants a magazine (MG: 20 rounds)",
"Jeder Ausgeschaltete verliert seine Erkennungsmarke. Sammle die Marken der Gegner ein, um Abschüsse zu bestätigen – und schnapp dir die Marken deiner Kameraden, bevor der Gegner es tut. Wer nur aus der Ferne schießt, punktet nicht.":"Everyone taken out drops their dog tag. Collect enemy tags to confirm kills – and grab your teammates’ tags before the enemy does. Shooting only from afar won’t score.",
"Jeder Handgriff selbst, keine Außenansicht, KI-Besatzung auf den anderen Plätzen.":"Every action yourself, no external view, AI crew on the other seats.",
"Jeder Handgriff selbst, keine Außenansicht.":"Every drill yourself, no external view.",
"Jeder Wiedereinstieg kostet ein Ticket":"Every respawn costs a ticket",
"Jeder eingesetzte Soldat kostet ein Verstärkungsticket":"Every deployed soldier costs a reinforcement ticket",
"Jeder für sich":"Every man for himself",
"Jeder gegen jeden":"Free-for-all",
"Jedes Wort ist eine Wahl.":"Every word is a choice.",
"Jet-Einsatz":"Jet sortie",
"Jet: Start von der Bahn, Luftkampf gegen Hubschrauber":"Jet: takeoff from the runway, dogfight against helicopters",
"Jet: W/S Schub, Maus neigen/rollen, A/D Seitenruder. Auf der Bahn Vollgas, ab etwa 250 km/h sanft ziehen.":"Jet: W/S throttle, mouse pitch/roll, A/D rudder. Full throttle on the runway, gently pull up from about 250 km/h.",
"Jetzt die zweite Stellung. Sie haben uns gehört – Verstärkung kommt!":"Now the second position. They heard us – reinforcements are coming!",
"Jetzt neu starten":"Restart now",
"Jetzt neu starten und installieren":"Restart and install now",
"Jetzt sind Sie raus. Das zählt.":"You’re out now. That’s what counts.",
"Jetzt weißt du es.":"Now you know.",
"Jetzt wird es laut, egal wie leise wir sind. Auf dein Zeichen, Falke!":"It’s getting loud now, no matter how quiet we are. On your signal, Falke!",
"Joystick":"Joystick",
"Joystick. Er erscheint, wo dein linker Daumen landet; ganz nach oben geschoben sperrt er den Sprint.":"Joystick. It appears where your left thumb lands; push it all the way up to lock sprint.",
"Juli":"July",
"Junge Tamo":"Young Tamo",
"Juni":"June",
"Jäger über uns! Runter!":"Fighters overhead! Get down!",
"K3 = Zug, K5 = Kp.":"C3 = platoon, C5 = coy",
"KA":"CN",
"KABEL NICHT KNICKEN":"DO NOT KINK CABLE",
"KEIL SCHLIESST SELBSTTÄTIG":"BREECH CLOSES AUTOMATICALLY",
"KEIN TRITT":"NO STEP",
"KETTE!":"TRACK!",
"KHS-4 Sperber: Kampf- und Transporthubschrauber. Bordschütze am 30-mm-Kinnturm – zielen mit Maus/rechtem Stick, feuern wie gewohnt.":"KHS-4 Sperber: attack and transport helicopter. Door gunner on the 30 mm chin turret – aim with mouse/right stick, fire as usual.",
"KI-Trupps":"AI squads",
"KM-7 Wespe mit Schalldämpfer: leise und ohne Mündungsfeuer – Wachen hören den Schuss kaum.":"KM-7 Wespe with suppressor: quiet and no muzzle flash – guards barely hear the shot.",
"KOPF EINZIEHEN":"MIND YOUR HEAD",
"KP-1 Mammut":"KP-1 Mammut",
"KP-1 Mammut: Kampfpanzer mit Wärmebild und Munitionsbunker, 4 Mann; zweiter Stellplatz: SZ-8 Igel (Schützenpanzer, 30 mm + Lenkflugkörper); dazu LP-21 Gämse (leicht, 105 mm) und Transporter RS-8 Waran (8×8, 30 mm), LKW-5, GMW-6, GW-7 (MG-Ring)":"KP-1 Mammut: main battle tank with thermal sight and ammo bustle, crew of 4; second slot: SZ-8 Igel (IFV, 30 mm + guided missiles); plus LP-21 Gämse (light, 105 mm) and transports RS-8 Waran (8×8, 30 mm), LKW-5, GMW-6, GW-7 (MG ring)",
"KP-1 und SZ-8: Wärmebild und Restlicht. KP-68 (1960er) und Weltkriegspanzer: nur Optik und Winkelspiegel. Munition passt zur Kanone – KP-68: Treibspiegel, Hohlladung, Quetschkopf, Kanister; SZ-8: 30-mm-Feuerstöße und Lenkflugkörper. Leicht: LP-21 (105 mm, schnell, dünn gepanzert), LP-39 (37 mm). Schwer: SP-58 (120 mm, 1950er), SP-45 (lange 88 mm, 150-mm-Bug).":"KP-1 and SZ-8: thermal and low-light. KP-68 (1960s) and world-war tanks: optics and periscopes only. Ammunition matches the gun – KP-68: APDS, HEAT, HESH, canister; SZ-8: 30 mm bursts and guided missiles. Light: LP-21 (105 mm, fast, thinly armored), LP-39 (37 mm). Heavy: SP-58 (120 mm, 1950s), SP-45 (long 88 mm, 150 mm bow).",
"KP-68 Auerochs: Gussturm, 105 mm, Infrarot-Scheinwerfer, 4 Mann; zweiter Stellplatz SP-58 Mastodon (schwer, 120 mm); Transporter MTW-13 Kröte (Ketten, MG), LKW-5, GMW-6":"KP-68 Auerochs: cast turret, 105 mm, infrared searchlight, crew of 4; second slot SP-58 Mastodon (heavy, 120 mm); transports MTW-13 Kröte (tracked, MG), LKW-5, GMW-6",
"KP-68 „Auerochs“ (nur Optik)":"KP-68 “Auerochs” (optics only)",
"KRAFTSTOFF 72 %":"FUEL 72 %",
"KT":"CS",
"KV-47, VP-9, QX-90 und Adler nach echten Fotos neu gebaut, dazu ZW-12 Zwilling, P-9A und PS-41 Wirbel und der Modus Stellung. Aus Gräben klettert man jetzt heraus. In VR gibt es Hände, beidhändiges Halten, Holster an Rücken und Hüfte und echtes Gehen im Raum.":"KV-47, VP-9, QX-90 and Adler rebuilt from real photos, plus ZW-12 Zwilling, P-9A and PS-41 Wirbel and the Hardpoint mode. You now climb out of trenches. In VR there are hands, two-handed holding, holsters on the back and hip and real room-scale walking.",
