"Kanister mit Fangnetz: Beim Aufschlag spannt sich ein beschwertes Netz über drei Meter. Wer darunter steht, kommt vier Sekunden kaum vom Fleck – kein Sprint, kein Sprung.":"Canister with a capture net: on impact a weighted net spreads over three meters. Whoever is underneath can barely move for four seconds – no sprint, no jump.",
