"Karabiner mit kurzem Lauf und Rotpunkt: schneller im Anschlag als jedes Sturmgewehr, ruhig im Dauerfeuer – auf lange Achsen verliert er dafür früher an Wucht.":"Short-barreled carbine with red dot: faster to aim than any assault rifle, steady on full auto – but it loses punch sooner over long sightlines.",
