"Kompakt, ruhig im Dauerfeuer und schneller im Anschlag als jeder Gegner, der um die Ecke kommt. Die Viper beißt zu, bevor das Gegenüber blinzelt – und bleibt bis in die Hofmitte gefährlich.":"Compact, steady on full auto and faster to aim than any enemy rounding the corner. The Viper bites before the other guy blinks – and stays dangerous out to the middle of the yard.",
"Kompakte Maschinenpistole mit Rückstoßumlenkung und über tausend Schuss pro Minute. Auf Türrahmen-Distanz ein Sturm – auf der Straße nur noch ein Summen.":"Compact SMG with recoil redirection and over a thousand rounds per minute. A storm at doorway range – out on the street just a buzz.",
