"Leutnant Wendt, Zug Kiesel. In den Gassen seid ihr blind – wir sind eure Augen. Und ihr seid unser Schild.":"Lieutenant Wendt, Pebble platoon. In the alleys you’re blind – we’re your eyes. And you’re our shield.",
"Libelle 1":"Libelle 1",
"Libelle 1 an Falke: Er ist unten. Du kannst jetzt aufhören, über ihn hinwegzudonnern. Landebahn ist frei – mach es ordentlich.":"Libelle 1 to Falke: he’s down. You can stop thundering over him now. Runway is clear – do it properly.",
"Libelle 1 hebt ab. Kurs Holzplatz, Höhe vierzig.":"Libelle 1 lifting off. Heading for the timber yard, altitude forty.",
"Libelle 1 im Anflug auf die Frontstellung. Zwanzig Sekunden!":"Libelle 1 inbound to the front line. Twenty seconds!",
"Libelle 1 ist abgestürzt.":"Libelle 1 has crashed.",
"Libelle 1 ist aufgetankt. Am Holzplatz steht Flugabwehr – zwei, drei Nester, vielleicht mehr. Ich kann nicht landen, solange die feuern.":"Libelle 1 is refueled. There’s anti-aircraft at the timber yard – two, three nests, maybe more. I can’t land while they’re firing.",
"Libelle 1, Kurs auf die Landezone. Noch zwei Minuten.":"Libelle 1, heading for the landing zone. Two minutes.",
"Licht":"Lights",
"Licht und Farben wurden an einem echten Video gemessen und nachgestellt: Pflaster, Dächer, Putz, Wellblech und Ziegel in diesem Stil, ein bewölkter Himmel als Standard, ein dichteres Dorf im Grenzland mit zehn eingerichteten Häusern und begehbare Hallen im Hafen. Die Soldaten bekamen Splittertarn, große Helme und Rucksäcke. Dazu die ersten Zivilfahrzeuge zum Selbstfahren: Limousine, Kastenwagen, Gabelstapler und Sattelzug.":"Light and colors were measured against a real video and recreated: paving, roofs, plaster, corrugated iron and brick in that style, an overcast sky as default, a denser village in Borderland with ten furnished houses and walkable halls in the Harbor. The soldiers got splinter camo, big helmets and backpacks. Plus the first civilian vehicles you can drive yourself: sedan, van, forklift and semi-truck.",
