"Maschinenpistole":"Submachine gun",
"Maschinenpistole der Weltkriegszeit aus Stahlrohr und Bakelit: gemächlicher Takt, gutmütig im Dauerfeuer, zweiunddreißig Schuss im Stangenmagazin. Der Magazinschacht ist zugleich der Vordergriff.":"World War–era SMG made of steel tube and Bakelite: leisurely cadence, forgiving on full auto, thirty-two rounds in a stick magazine. The magazine well doubles as the foregrip.",
"Maschinenpistole mit eingebautem Schalldämpfer über die ganze Lauflänge: kein Mündungsfeuer, kaum ein Knall – nur das Klacken des Verschlusses. Leise ist sie nicht wehrlos, aber auf Distanz verliert sie schnell an Wucht.":"SMG with an integral suppressor along the whole barrel: no muzzle flash, hardly a bang – just the clack of the bolt. Quiet doesn’t mean harmless, but it loses punch quickly at range.",
