"Mehrspieler: Browser-, Handy- und VR-Spieler sind in denselben Räumen, wenn alle dieselbe Spielfassung haben. Einladungslinks aus der App führen auf die Webseite.":"Multiplayer: browser, phone and VR players share the same rooms if everyone has the same game version. Invite links from the app lead to the website.",
"Mehrstöckiger Häuserkampf":"Multi-story house-to-house fighting",
"Mehrzweck":"Multi-terrain",
"Mehrzweckgranate":"Multi-purpose round",
"Meilensteine":"Milestones",
"Mein Befehl lautete, heute Morgen mit Kessar zu marschieren. Ich habe ihn verweigert. Zweihundert meiner Leute auch.":"My orders were to march with Kessar this morning. I refused. So did two hundred of my men.",
"Mein Bein trägt mich noch nicht in ein Cockpit. Aber auf der Bahn steht ein JK-9, vollgetankt. Falke, du hattest zwölf Stunden im Simulator in Hohenfeld.":"My leg won’t carry me into a cockpit yet. But there’s a JK-9 on the runway, fully fueled. Falke, you had twelve hours in the simulator at Hohenfeld.",
"Mein Großvater Emil war zweiundzwanzig. Sein Panzer hieß Bison, und sein Zielfernrohr war alles, was er hatte.":"My grandfather Emil was twenty-two. His tank was called Bison, and his gunsight was all he had.",
"Mein Großvater hat einmal gesagt: An der Furt von Mirenfurt entscheidet sich jeder Krieg in diesem Tal. Er war dabei – vor achtzig Jahren.":"My grandfather once said: every war in this valley is decided at the ford of Mirenfurt. He was there – eighty years ago.",
"Mein Ziel war von Anfang an: so realistisch wie möglich, irgendwo zwischen CS:GO, Battlefield und Bodycam. An diesem Tag kamen der Hafen und das Werk dazu, Bots, die Deckung suchen und flankieren, Fotoscan-Texturen und echte Tonaufnahmen für die Waffen. Weil ich auch Fahrzeuge wollte, entstand die große Karte Grenzland mit Dorf, Bauernhof, Industrie und einer Brücke, samt ein paar versteckten Geheimnissen.":"My goal from the start: as realistic as possible, somewhere between CS:GO, Battlefield and Bodycam. That day brought the Harbor and the Factory, bots that seek cover and flank, photo-scanned textures and real sound recordings for the weapons. Because I also wanted vehicles, the big map Borderland was created, with a village, a farm, industry and a bridge, plus a few hidden secrets.",
"Meine Brigade hält die Straße nach Osten. Aber die Graue Kompanie kommt nicht über Straßen. Sie kommt durch die Trichter.":"My brigade holds the road to the east. But the Gray Company doesn’t come by road. It comes through the craters.",
"Meine Freunde testen.":"My friends test it.",
"Meine Laufbahn ist mir weniger wert als die Menschen in diesem Tal.":"My career is worth less to me than the people in this valley.",
"Meine Leute haben heute gegen Männer gekämpft, mit denen sie gestern noch gegessen haben. Das vergessen sie nicht.":"Today my men fought against men they were eating with yesterday. They won’t forget that.",
"Meine Leute? Ilja, du verstehst es immer noch nicht. Ich war nie derjenige, der bezahlt hat.":"My people? Ilja, you still don’t get it. I was never the one who paid.",
