"Muss ich etwas herunterladen?":"Do I need to download anything?",
"Muss man sich vor KI fürchten? Ich finde nicht. Mit Respekt sollte man ihr aber begegnen: Sie entwickelt sich rasant, und es lohnt sich, wachsam zu bleiben, wohin die Reise in den kommenden Jahren geht. Das ändert nichts daran, dass wir heute leben, und heute kann KI genau die Lücken füllen, die man selbst hat. Bei mir war das das Programmieren.":"Should we be afraid of AI? I don’t think so. But we should treat it with respect: it’s developing rapidly, and it’s worth staying alert to where things are heading in the coming years. That doesn’t change the fact that we live today, and today AI can fill exactly the gaps you have yourself. For me, that was programming.",
