"Nur für Spieler der ersten Stunde. Bis zu drei eigene Muster – danach in der Tarnungsauswahl jeder Waffe. Online sehen die anderen dein Muster.":"Day-one players only. Up to three custom patterns – then available in every weapon’s camo selection. Online, others see your pattern.",
"Nur für Spieler der ersten Stunde: Karabiner mit goldenen Ringen und dem Nullpunkt-Zeichen. Liegt zwischen M-17 und K-36 – etwas mehr Wucht als der K-36, etwas langsamer – ruhig im Dauerfeuer, keine Wunderwaffe.":"Day-one players only: carbine with golden rings and the Nullpunkt emblem. Sits between the M-17 and K-36 – a bit more punch than the K-36, a bit slower – steady on full auto, no wonder weapon.",
"Nur für Spieler der ersten Stunde: Pistole mit goldenem Kompensator. Etwas mehr Wucht und weniger Rückstoß als die P-9, dafür ein Schuss weniger im Magazin.":"Day-one players only: pistol with golden compensator. A bit more punch and less recoil than the P-9, but one round fewer in the magazine.",
"Nur für Spieler der ersten Stunde: zweischneidiger Dolch mit goldener Parierstange. Zwei Stiche wie das Kampfmesser, von hinten einer – etwas schneller im Stoß, dafür kürzer.":"Day-one players only: double-edged dagger with golden crossguard. Two stabs like the combat knife, one from behind – slightly faster thrust, but shorter.",
"Nur für flüssiges Drehen.":"Only for smooth turning.",
