"Nur mit Handschuhen greifen":"Handle with gloves only",
"Nur mit Maus oder Controller.":"Mouse or controller only.",
"Nur mit verbündeten Bots: halten und in Richtung ziehen oder antippen und Befehl wählen.":"Only with allied bots: hold and drag in a direction, or tap and choose an order.",
"Nur mit voller Nachbearbeitung.":"Full post-processing only.",
"Nur mit vorheriger schriftlicher Erlaubnis von German Legend:":"Only with prior written permission from German Legend:",
"Nur per Knopf/Taste":"Button/key only",
"Nur wenn du einen Raum öffnest oder beitrittst, verlassen Daten das Gerät; NULLPUNKT selbst speichert davon nichts. Den Verbindungsaufbau vermitteln öffentliche Nostr-Relays (verschlüsselt, ohne Konto), STUN-Server von Google und Cloudflare helfen beim Finden der Verbindung. Danach spielen die Browser direkt miteinander (WebRTC) – dabei sehen die Mitspieler im Raum technisch deine IP-Adresse. Sichtbar sind außerdem dein Spielername, Team, Stufe und Gerät. Öffentliche Spiele stehen mit Raumcode, Name des Hosts und Karte in einer öffentlichen Liste. Einen eigenen Spielserver gibt es nicht.":"Data only leaves your device when you open or join a room; NULLPUNKT itself stores none of it. Public Nostr relays (encrypted, no account) broker the connection, and STUN servers from Google and Cloudflare help find it. After that the browsers play directly with each other (WebRTC) – the other players in the room can technically see your IP address. Your player name, team, level and device are also visible. Public games are listed with room code, host name and map in a public list. There is no dedicated game server.",
