"Panzerabwehr-Rohr der Pioniere: Raketengranate mit Hohlladung. Knackt Geländewagen mit einem Treffer in die Flanke, Kampfpanzer mit zweien ins Heck – und räumt jede Stellung.":"The engineers’ anti-tank tube: rocket grenade with shaped charge. Cracks an off-road vehicle with one hit to the flank, a main battle tank with two to the rear – and clears any position.",
