"Panzerbesatzung: leichte Weste, MP und Pistole, Rauch- und Splittergranate, Fernglas; wechselt im Panzer doppelt so schnell den Sitz, lädt 25 % schneller und repariert das eigene Fahrzeug im Notfall.":"Tank crew: light vest, SMG and pistol, smoke and frag grenade, binoculars; switches seats twice as fast in a tank, loads 25 % faster and repairs their own vehicle in an emergency.",
