"Programmieren ist dabei nur ein Einsatzgebiet. KI kann zum Beispiel auch Musik erzeugen, das sehe ich allerdings kritischer, denn Musik ist für mich echte Kunst. Programmieren ist für mich eher Handwerk: Hobby, Leidenschaft und eine Frage des Könnens. Weil mir genau dieses Können fehlt, habe ich mir Claude an die Seite geholt.":"Programming is only one area of use. AI can also create music, for example, but I see that more critically, because to me music is real art. Programming is more of a craft to me: a hobby, a passion and a matter of skill. Because I lack exactly that skill, I brought Claude on board.",
