"Seyfried hat gezahlt, was er zahlen sollte. Er wird nicht mehr gebraucht. Doktor Pell – Sie wissen, wohin Sie gehen.":"Seyfried has paid what he was supposed to pay. He is no longer needed. Doctor Pell – you know where you’re going.",
