"Teleport: linken Stick nach vorn halten, Bogen auf den Boden richten, loslassen – kurzes Abblenden, keine Bewegung im Bild. Am angenehmsten bei Übelkeit.":"Teleport: hold the left stick forward, aim the arc at the ground, release – brief fade, no motion on screen. Most comfortable if you get nauseous.",
