"Teleskop-Schlagstock aus Stahl: zwei schnelle Schläge. Spezial „Betäuben“: jeder Treffer lässt den Gegner 1,5 s lang schwer vorankommen.":"Steel telescopic baton: two quick strikes. Special “Stun”: every hit slows the enemy heavily for 1.5 s.",
"Tempo":"Speed",
"Test beendet.":"Test ended.",
"Teste jede Waffe in Ruhe: Klappziele auf verschiedenen Distanzen, unbegrenzte Reservemunition und eine Trefferstatistik, die nicht lügt. Rund um den Stand liegt das Übungsgelände: alle Panzer, Transporter, Autos, Hubschrauber und Jets zum Einsteigen, eine Fahrstrecke, die Panzerschießbahn bis 2500 m mit Trefferanzeige und ein Flugfeld mit Luft- und Bodenzielen – allein, ohne Gegner.":"Test every weapon in peace: pop-up targets at various distances, unlimited reserve ammo and hit stats that don’t lie. Around the range lies the training ground: every tank, transport, car, helicopter and jet to get into, a driving course, the tank gunnery range out to 2500 m with hit display and an airfield with air and ground targets – alone, without enemies.",
