"Tipp: Blutungen stillst du mit Verband oder Abbinden, bevor das Bild grau wird.":"Tip: Stop bleeding with a bandage or tourniquet before your vision goes grey.",
"Tipp: Controller? Steuerkreuz wählt, A bestätigt, B geht zurück.":"Tip: Controller? D-pad selects, A confirms, B goes back.",
"Tipp: Das Übungsgelände hat jedes Fahrzeug zum Einsteigen – ohne Gegner.":"Tip: The training ground has every vehicle to climb into – with no enemies.",
"Tipp: Dauerfeuer frisst sich durch dünne Wände. Deckung ist nicht gleich Schutz.":"Tip: Sustained fire eats through thin walls. Cover isn’t the same as protection.",
"Tipp: Fünf Schuss auf den Punkt im Hauptmenü schießen die Waffe ein.":"Tip: Five shots at the dot in the main menu zero your weapon.",
"Tipp: Gehockt und still stehend streut jede Waffe am wenigsten.":"Tip: Every weapon is most accurate when you crouch and stand still.",
"Tipp: Grafik ruckelt? Unter Einstellungen eine Stufe niedriger wählen.":"Tip: Graphics stuttering? Choose one level lower in the settings.",
"Tipp: Halbleere Magazine bleiben in der Simulation halbleer. Zähl mit.":"Tip: In simulation, half-empty magazines stay half-empty. Keep count.",
"Tipp: Im Panzer sagt der Kommandant das Ziel an – Richtschütze, Panzer, halbrechts, 800, Feuer.":"Tip: In the tank the commander calls the target – gunner, tank, half right, 800, fire.",
