"Unberührbar":"Untouchable",
"Und Hauptmann Elias Brandt, Nordkorps. Die Waffenruhe gilt – für beide Seiten, ab sofort und ohne Ausnahme. Niemand schießt, der nicht muss.":"And Captain Elias Brandt, North Corps. The ceasefire stands – for both sides, effective immediately and without exception. Nobody shoots who doesn’t have to.",
"Und achtet auf die Trupps mit Panzerfäusten. Die kommen leise durchs hohe Gras.":"And watch out for the teams with rocket launchers. They come quietly through the tall grass.",
"Und auf dem Vorfeld wird ein Hubschrauber betankt. Zivil lackiert, aber mit Zusatztanks. Weit genug für jedes Land, das keine Fragen stellt.":"And a helicopter is being refueled on the apron. Civilian paint, but with extra tanks. Far enough for any country that asks no questions.",
"Und danke an dich fürs Spielen. Über dein Feedback freue ich mich.":"And thank you for playing. I look forward to your feedback.",
"Und der Kapitän? Anselm Vogt. Sie halten ihn im Kaibüro fest. Seine Familie haben sie bedroht, damit er fährt.":"And the captain? Anselm Vogt. They’re holding him in the quay office. They threatened his family to make him sail.",
"Und der dritte?":"And the third?",
"Und die Brigade von Major Daren hat Befehl, mitzumarschieren.":"And Major Daren’s brigade has been ordered to march with him.",
"Und diesmal kommen wir alle heim.":"And this time we all come home.",
"Und niemand schießt, der nicht muss. Wir sind nicht wie Kessar.":"And nobody shoots who doesn’t have to. We’re not like Kessar.",
"Und schießt nicht in die Kirche. Da drin sitzen noch Leute aus der Stadt.":"And don’t fire into the church. There are still townspeople inside.",
"Und warum sollten wir Ihnen trauen?":"And why should we trust you?",
"Und wenn es losgeht: Die Geiseln sitzen mitten zwischen ihnen. Jeder Schuss muss sitzen.":"And when it starts: the hostages are sitting right among them. Every shot has to count.",
"Und wenn sie wirklich unsere Uniformen tragen?":"And if they really are wearing our uniforms?",
"Und wer sind die beiden Stimmen? Die eine bin ich. Die andere ist eine KI. NULLPUNKT ist nämlich auch ein kleines Experiment.":"And who are the two voices? One is me. The other is an AI. Because NULLPUNKT is also a small experiment.",
"Unentdeckt":"Undetected",
"Unentdeckt über die Kaimauer (Entdeckungsanzeige, Alarm)":"Cross the quay wall undetected (detection meter, alarm)",
"Unentschieden":"Draw",
"Ungültig.":"Invalid.",
"Ungültige Markierung.":"Invalid marker.",
"Universal-MG der Weltkriegszeit mit gelochtem Laufmantel und Gurttrommel: über tausend Schuss pro Minute, das Geräusch eines reißenden Tuchs. Wer ihn nicht festhält, schießt in den Himmel.":"World War–era general-purpose MG with perforated barrel jacket and belt drum: over a thousand rounds per minute, the sound of tearing cloth. Don’t hold it tight and you’ll shoot at the sky.",
"Unser Beobachtungsposten am Panzerwrack ist in der Nacht überrannt worden. Mit ihm das Artillerie-Funkgerät.":"Our observation post at the tank wreck was overrun during the night. And with it the artillery radio.",
"Unser Turmantrieb muss in die Werkstatt. Aber in der Reserve steht noch der alte Auerochs. Der hat schon meinen Vater gefahren.":"Our turret drive needs the workshop. But the old Auerochs is still in reserve. It already carried my father.",
"Unsere Frauen sind im ersten Lkw? Dann gehen wir. Danke.":"Our wives are on the first truck? Then we’ll go. Thank you.",
