"Wir bleiben dicht bei dir, Falke.":"We’re staying close to you, Falke.",
"Wir bleiben hier am Zaun. Drei Posten. Einer geht Streife zwischen Scheune und Tank. Leise, Falke.":"We stay here at the fence. Three sentries. One patrols between barn and tank. Quietly, Falke.",
"Wir bluten aus":"We are bleeding out",
"Wir brauchen ihn lebend. Vor einem Gericht – nicht als Märtyrer für seine Anhänger.":"We need him alive. In front of a court – not as a martyr for his followers.",
"Wir dachten, niemand kommt. Das Feuer war schon am Sägewerk.":"We thought nobody would come. The fire had already reached the sawmill.",
"Wir gehen durch die Marktgasse, dann übers Torhaus zum Brunnenplatz. Leise, solange es geht.":"We go through Market Lane, then via the gatehouse to Fountain Square. Quietly, as long as we can.",
