"Wir halten dir den Rücken frei! Finger weg vom roten Kabel – das hat Krell dir beigebracht!":"We’ve got your back! Hands off the red wire – Krell taught you that!",
"Wir halten {0}{1}.":"We’re holding {0}{1}.",
"Wir halten {p}!":"We’re holding {p}!",
"Wir hören euch! Kommt nach Süden, am Kai entlang – wir halten euch den Weg frei!":"We hear you! Come south along the quay – we’ll keep the way clear!",
"Wir landen. Wir landen! Nicht schießen!":"We’re landing. We’re landing! Don’t shoot!",
"Wir markieren sie für die Pioniere. Kein Alarm – sonst jagen sie die Ladung hoch, bevor wir sie sichern.":"We mark them for the engineers. No alarm – or they’ll blow the cargo before we secure it.",
"Wir müssen nicht siegen, Lenz. Wir müssen nur lange genug stehen, bis der letzte Lkw draußen ist.":"We don’t have to win, Lenz. We just have to stand long enough for the last truck to get out.",
"Wir sehen dich auf der Galerie. Leg an und halte die Wachen kurz im Visier – dann sind sie markiert.":"We see you on the gallery. Aim and keep the guards in your sights briefly – then they’re marked.",
"Wir sind eine Handvoll gegen eine Brigade, Herr Hauptmann.":"We’re a handful against a brigade, Captain.",
"Wir sind getroffen!":"We’re hit!",
"Wir verhandeln nicht mehr in Zelten und Kasernen. Die Menschen sollen sehen, was beschlossen wird – und wer es beschließt.":"We no longer negotiate in tents and barracks. People should see what is decided – and who decides it.",
"Wird auf diesem Gerät gespeichert.":"Saved on this device.",
"Wird dir beim Spielen übel? Kamerabewegung und Waffenträgheit senken, Fischauge verringern, Sichtfeld erhöhen – oder die Vorlage „Bodycam · Komfort“. Ganz ohne HUD wie bei Bodycam: HUD → „Realismus“.":"Feeling sick while playing? Lower camera motion and weapon inertia, reduce fisheye, raise field of view – or use the “Bodycam · Comfort” preset. No HUD at all, like bodycam footage: HUD → “Realism”.",
