"Zehn Abschüsse, ohne zu sterben.":"Ten kills without dying.",
"Zehn Freunde gleichzeitig in einem Match, und alles hat gehalten: ein voller Erfolg. Danach ging es direkt weiter: Verletzungen mit Verband und Wiederbeleben, neue Nahkampfwaffen wie Axt und Schlagstock, Fassaden, die nach Explosionen herausbrechen, Autos, die sich verformen, Fenster zum Zerschießen, über 20 Waffenaufsätze und die Stellungskriegskarte Niemandsland mit Gräben, die man mit dem Spaten selbst tiefer graben kann.":"Ten friends in one match at the same time, and everything held up: a complete success. Then it went straight on: wounds with bandaging and reviving, new melee weapons like an axe and a baton, facades that break out after explosions, cars that deform, windows to shoot out, over 20 weapon attachments and the trench-warfare map No Man’s Land, with trenches you can dig deeper yourself with a spade.",
