"Zum Versorgungspunkt fahren (Kiste auf der Minikarte)":"Drive to the supply point (crate on the minimap)",
"Zum ersten Mal habe ich das Spiel Freunden gezeigt. Zurück kam eine lange Fehlerliste: eine unsichtbare Wand an einer Treppe, schwebende Lampen und eine Waffe, die an Wänden nach oben klappt. Alles wurde abgearbeitet. Die Karten wurden um ein Viertel größer und bekamen mehr Deckung, die Bots lernen seitdem von den Spielern und kämpfen bis zu 32 gegen 32. Ich wollte Grafik wie in der Unreal Engine 5. Die KI hat mir ehrlich gesagt, dass das im Browser so nicht geht, und dann herausgeholt, was möglich ist.":"For the first time I showed the game to friends. Back came a long bug list: an invisible wall on a staircase, floating lamps and a weapon that flips upward against walls. Everything was worked through. The maps grew by a quarter and got more cover, and since then the bots learn from the players and fight up to 32 vs 32. I wanted graphics like Unreal Engine 5. The AI honestly told me that isn’t possible like that in a browser, and then got out of it what is possible.",
"Zur Galerie":"To the gallery",
"Zur Markierung":"To marker",
"Zur Website":"To website",
"Zureden":"Talking them down",
"Zurück":"Back",
"Zurück auf die Höhe! Die Stellung darf nicht fallen.":"Back up the hill! The position must not fall.",
"Zurück in Sant Aurel, diesmal am Abend und unter Zeitdruck: Kessar will über das Relais im Glockenturm gefälschte Angriffsbefehle an alle Einheiten senden. Lenz liegt im Lazarett – Falk führt den Trupp zum ersten Mal selbst. Die Einwohner suchen Schutz in der Kirche am Brunnenplatz. Das Relais wird rechtzeitig abgeschaltet; ein gefangener Funker verrät, dass Kessar zum Fliegerhorst Hagenmoor flieht.":"Back in Sant Aurel, this time in the evening and against the clock: Kessar wants to send forged attack orders to every unit via the bell tower relay. Lenz is in the field hospital – Falk leads the squad himself for the first time. The townspeople take shelter in the church on Fountain Square. The relay is shut down in time; a captured radio operator reveals that Kessar is fleeing to Hagenmoor Air Base.",
"Zurück in den Raum":"Back to the room",
"Zurück zum Gewehr":"Back to the rifle",
"Zurück zum Sammelpunkt":"Return to the rally point",
"Zurück zur Kapelle. Da draußen liegen noch Verwundete.":"Back to the chapel. There are still wounded out there.",
"Zurück zur Website":"Back to website",
"Zurückgesetzt. Extrem nutzt wieder 8K-Schatten, wo die Grafikkarte es kann.":"Reset. Extreme uses 8K shadows again where the GPU can handle it.",
