"Zwei Abschüsse innerhalb von vier Sekunden.":"Two kills within four seconds.",
"Zwei Begleithubschrauber abschießen":"Shoot down two escort helicopters",
"Zwei Gegner mit einer einzigen Kugel.":"Two enemies with a single bullet.",
"Zwei Geländewagen mit schweren MGs! Sie wollen durchbrechen!":"Two off-road vehicles with heavy MGs! They want to break through!",
"Zwei Holzbrücken quer über die Halle":"Two wooden bridges across the hall",
"Zwei Kampfpanzer ausschalten":"Knock out two main battle tanks",
"Zwei Kranich sind bekannt. Einer fehlt.":"Two Kranich are known. One is missing.",
"Zwei Nächte nach Kessars Festnahme hat Weber die fremde Stimme angepeilt: Sie sendet vom Funkhügel im Grenzland. Mit Nachtsichtgeräten schleicht der Trupp vom Gehöft über die Furt, schaltet Streifen lautlos aus und stürmt den Bunker der „Grauen Kompanie“ – Söldner ohne Hoheitszeichen. Ihr Anführer Jaro Vahl entkommt, aber Webers Kopie des Funkrechners verrät Phase zwei: einen Anschlag auf die öffentliche Sitzung der Kommission in Veldmark.":"Two nights after Kessar’s arrest, Weber has located the strange voice: it transmits from the radio hill in the Borderland. With night vision goggles the squad sneaks from the farmstead across the ford, silently takes out patrols and storms the bunker of the “Gray Company” – mercenaries without insignia. Their leader Jaro Vahl escapes, but Weber’s copy of the radio computer reveals phase two: an attack on the commission’s public session in Veldmark.",
"Zwei Panzer jenseits der Brücke! Panzergranate laden – und in Bewegung bleiben!":"Two tanks beyond the bridge! Load AP – and keep moving!",
"Zwei Panzer, Zwölf Uhr, auf der Straße. Wir schießen zuerst.":"Two tanks, twelve o’clock, on the road. We fire first.",
"Zwei Patronen im Lager – Doppelzuführung!":"Two rounds in the chamber – double feed!",
"Zwei Streifen am Feldweg, eine an der Furt. Du kannst sie umgehen – oder leise abräumen. Deine Entscheidung.":"Two patrols on the field track, one at the ford. You can go around them – or quietly clear them. Your call.",
"Zwei Teams, eine Rechnung: Jeder Abschuss zählt, jeder Tod kostet. Schnelle Wiedereinstiege halten das Tempo hoch – Flanken, Deckung und Serienprämien entscheiden das Match.":"Two teams, one score: every kill counts, every death costs. Quick respawns keep the pace high – flanks, cover and killstreaks decide the match.",
"Zwei Teams, nur Messer: keine Schusswaffen, keine Granaten, keine Serienprämien. Wer schneller um die Ecke ist, gewinnt das Duell – Flanken und Überraschung entscheiden.":"Two teams, knives only: no firearms, no grenades, no killstreaks. Whoever gets around the corner faster wins the duel – flanks and surprise decide.",
"Zwei Transporter verloren – die Kolonne kann nicht weiter.":"Two trucks lost – the column can’t continue.",
"Zwei Weichkern-Platten. Kaum spürbar, fängt eine kurze Salve ab.":"Two soft-core plates. Barely noticeable, stops a short burst.",
"Zwei auf einen Streich":"Two with one blow",
"Zwei kommen die Marktgasse herunter! Familie runter, Falke vorn!":"Two coming down Market Lane! Family get down, Falke up front!",
"Zwei leichte MGs halten Gegner nieder, Schützen und ein Sanitäter sichern.":"Two light MGs pin the enemy down, riflemen and a medic provide security.",
"Zwei neue Großkarten, Flugplatz und Stadtkern, Relief auf allen großen Karten und viel Kleinkram auf den Straßen. 82 Materialien sind echte Fotoscans von Poly Haven (frei, CC0), auf Ultra in doppelter Auflösung.":"Two new large maps, Airfield and City Center, terrain relief on all large maps and lots of small details on the streets. 82 materials are real photo scans from Poly Haven (free, CC0), at double resolution on Ultra.",
"Zwei von drei. Der letzte steht am Westrand, fast am Kai.":"Two of three. The last one is at the western edge, almost at the quay.",
"Zweibein":"Bipod",
"Zweimal kurz drücken: Verschluss ein Stück zurück – liegt eine Patrone im Lager? Ohne Patrone im Lager klickt es beim Abziehen nur.":"Press twice quickly: bolt back a little – is there a round in the chamber? Without one, pulling the trigger only clicks.",
"Zweite Gruppe von Süden! Sie wollen die Kirche als Deckung!":"Second group from the south! They want the church as cover!",
"Zweite Stimme":"Second voice",
"Zweite Taste bei gehaltener erster = Kombination (z. B. LT + L3). Menü-Taste bricht ab.":"Second button while holding the first = combination (e.g. LT + L3). Menu button cancels.",
"Zweite Welle":"Second wave",
"Zweite Welle abwehren (Panzer und Schützenpanzer)":"Repel the second wave (tanks and IFVs)",
"Zweiter":"Second",
"Zweiter Feuerknopf für den linken Daumen.":"Second fire button for the left thumb.",
"Zweiter Lkw ist raus. Der letzte wird beladen – haltet durch.":"Second truck is out. The last one is loading – hold on.",
"Zweiter: dunkle Jacke, helles Hemd, bei der Treppe zur U-Bahn. Er zählt die Ausgänge.":"Second: dark jacket, light shirt, by the subway stairs. He’s counting the exits.",
"Zweitwaffe":"Secondary weapon",
"Zweitwaffe für Notfälle: blitzschnell gezogen, leicht geführt.":"Sidearm for emergencies: drawn in a flash, easy to handle.",
"Zwing Seyfried mit dichten Überflügen zur Landung (unter 150 m)":"Force Seyfried to land with close passes (below 150 m)",
