"vom Host":"by the host",
"von Anthropic. Lesen und verstehen kann ich Code, ihn selbst zu schreiben liegt mir aber nicht. Diesen Teil hat Claude übernommen und meine Vorstellungen Zeile für Zeile umgesetzt. Da in NULLPUNKT fast alles aus Code entsteht, gilt das auch für Modelle, Karten und Klänge: gebaut nach meinen Vorgaben und so lange nachgebessert, bis sie gepasst haben. Ergänzt wird das durch freie Texturen und Umgebungslicht von Poly Haven und ambientCG.":"by Anthropic. I can read and understand code, but writing it myself isn’t my thing. Claude took over that part and turned my ideas into reality line by line. Since almost everything in NULLPUNKT is made from code, that goes for models, maps and sounds too: built to my specifications and reworked until they were right. On top of that come free textures and environment lighting from Poly Haven and ambientCG.",
"von {0} MB · Budget „{1}“":"of {0} MB · budget “{1}”",
