"wählt das Spiel beim ersten Start selbst (kurzer Grafiktest) und lernt aus den ersten Runden. Ändern kannst du sie jederzeit.":"is chosen by the game on first launch (short graphics test) and learns from the first rounds. You can change it anytime.",
